MoviePreviewCard:
query MoviePreviewCard($movieId: Long!, $actorsLimit: Int!, $withUserData: Boolean = false, $seasonSubscriptionsSupported: Boolean = false) {
  movie(id: $movieId) {
    id
    contentId
    title {
      russian
      original
      __typename
    }
    ... on Film {
      productionYear
      isShortFilm
      ratingLists {
        top250 {
          movieListSlug
          position
          __typename
        }
        __typename
      }
      __typename
    }
    ... on TvSeries {
      releaseYears {
        start
        end
        __typename
      }
      __typename
    }
    ... on MiniSeries {
      releaseYears {
        start
        end
        __typename
      }
      __typename
    }
    ... on TvShow {
      releaseYears {
        start
        end
        __typename
      }
      __typename
    }
    ... on Video {
      productionYear
      __typename
    }
    ticketOption {
      purchasable
      __typename
    }
    viewOption(context: {seasonSubscriptionsSupported: $seasonSubscriptionsSupported}) {
      buttonText
      originalButtonText
      isAvailableOnline: isWatchable(filter: {anyDevice: false, anyRegion: false})
      purchasabilityStatus
      promotionIcons {
        avatarsUrl
        fallbackUrl
        __typename
      }
      type
      rightholderLogoUrlForPoster
      __typename
    }
    actors: members(limit: $actorsLimit, role: [ACTOR, CAMEO, UNCREDITED]) {
      items {
        person {
          id
          name
          originalName
          __typename
        }
        __typename
      }
      total
      __typename
    }
    directors: members(role: DIRECTOR, limit: 4) {
      items {
        person {
          id
          name
          originalName
          __typename
        }
        __typename
      }
      __typename
    }
    rating {
      kinopoisk {
        value
        isActive
        count
        __typename
      }
      __typename
    }
    poster {
      avatarsUrl
      fallbackUrl
      __typename
    }
    ...MoviePreviewUserData @include(if: $withUserData)
    __typename
  }
}

fragment MoviePreviewUserData on Movie {
  userData {
    voting {
      value
      votedAt
      __typename
    }
    isPlannedToWatch
    __typename
  }
  __typename
}

MovieSetVote:
mutation MovieSetVote($movieId: Long!, $rate: Int!) {
  movie {
    vote {
      set(input: {movieId: $movieId, rate: $rate}) {
        error {
          message
          __typename
        }
        status
        __typename
      }
      __typename
    }
    __typename
  }
}

MovieRemoveVote:
mutation MovieRemoveVote($movieId: Long!) {
  movie {
    vote {
      remove(input: {movieId: $movieId}) {
        error {
          message
          __typename
        }
        status
        __typename
      }
      __typename
    }
    __typename
  }
}
